3	import java.util.List;
4	
5	/**
6	 * 分段提交不变量的纯逻辑校验，不涉及数据库与事务。
7	 *
8	 * <p>规则（违反任一则提交被拒绝，不写入）：
9	 * <ul>
10	 *   <li>elapsedMillis 取值 1~86400000；</li>
11	 *   <li>elapsedMillis 必须严格小于该选手已有原始完赛耗时（无完赛耗时也拒绝）；</li>
12	 *   <li>同一选手同一检查点最多一条；</li>
13	 *   <li>允许乱序到达，但按检查点顺序查看时耗时必须严格递增：
14	 *       新记录必须严格大于已存在的最近前序检查点耗时，
15	 *       并严格小于已存在的最近后序检查点耗时。</li>
16	 * </ul>
17	 */
18	public final class CheckpointRules {
19	
20	    /** 分段耗时上界（毫秒），含端点：1天。 */
21	    public static final long MAX_ELAPSED_MILLIS = 86_400_000L;
22	
23	    private CheckpointRules() {
24	    }
25	
26	    /**
27	     * 校验一次分段提交。
28	     *
29	     * @param existingForRunner 该选手已存在的全部分段记录（任意顺序）
30	     * @param targetPosition    本次提交检查点的顺序
31	     * @param elapsedMillis     本次提交的累计耗时
32	     * @param finishTimeMs      该选手已有原始完赛耗时；null 表示尚无完赛计时
33	     * @return 违反不变量时的错误信息；合法时为 null
34	     */
35	    public static String validate(
36	            List<? extends TimingView> existingForRunner,
37	            int targetPosition,
38	            long elapsedMillis,
39	            Long finishTimeMs) {
40	        if (elapsedMillis < 1L || elapsedMillis > MAX_ELAPSED_MILLIS) {
41	            return "分段耗时毫秒数必须在 1~86400000 之间";
42	        }
43	        if (finishTimeMs == null) {
44	            return "选手尚无原始完赛耗时，不能提交分段记录";
45	        }
46	        if (elapsedMillis >= finishTimeMs) {
47	            return "分段耗时必须严格小于该选手原始完赛耗时";
48	        }
49	
50	        TimingView predecessor = null;
51	        TimingView successor = null;
52	        for (TimingView timing : existingForRunner) {
53	            if (timing.position() == targetPosition) {
54	                return "同一选手同一检查点最多一条分段记录";
